#include <algorithm>
#include <iostream>
#include <vector>
#include <ranges>

int main() {
    using namespace std;
    unsigned N;
    cin >> N;

    vector<unsigned> A(N);
    for (auto&& a : A)
        cin >> a;

    // 判定関数
    // K 個の鏡餅を作ることができるか？
    const auto check{
        [N, &A](unsigned K) {
            for (unsigned i = 0; i < K; ++i)
                // 先頭と末尾から K 個ずつ取ってきて
                if (A[i] * 2 > A[N - K + i])
                    // どれか 1 つでも半分より大きかったら false
                    return false;
            // そうでなければ true
            return true;
        }
    };

    // 0 から N / 2 の間で、判定関数が true になる最大の値（false になる最小の値 - 1）を二分探索で求める
    cout << *ranges::partition_point(views::iota(0U, N / 2 + 1), check) - 1 << endl;

    return 0;
}

#include <iostream>
#include <deque>

int main() {
    using namespace std;
    unsigned N;
    cin >> N;

    // 餅列の先頭側 floor(N / 2) 個
    deque<unsigned> A(N / 2);
    for (auto&& a : A)
        cin >> a;

    unsigned ans{};

    for (unsigned i{N / 2}; i < N; ++i) {
        unsigned a;
        cin >> a;
        // もし残っているうち最小の餅と鏡餅を作れるなら作る
        if (A.front() * 2 <= a) {
            ++ans;
            A.pop_front();
        }
    }

    cout << ans << endl;

    return 0;
}

#include <iostream>
#include <vector>

int main() {
    using namespace std;
    unsigned N;
    cin >> N;

    vector<unsigned> A(N);
    for (auto&& a : A)
        cin >> a;

    for (unsigned i = 0, j = 0, d = 0; i < N; ++i) {
        // j := i 番目の餅を乗せられる最小の餅の番号
        while (j < N && A[i] * 2 > A[j]) ++j;
        // d := 上下の餅の番号の差の最大値
        d = max(d, j - i);

        // 後ろがはみ出したら
        if (i + max(d, i + 1) >= N) {
            // 直前の値が答え
            cout << i << endl;
            return 0;
        }
    }
    return 0;
}
